from collections import Counter

class Solution:
    def intersection(self, nums: list[list[int]]) -> list[int]:
        cnt = Counter()
        for arr in nums:
            for x in arr:
                cnt[x] += 1
        n = len(nums)
        return sorted([x for x, c in cnt.items() if c == n])

class Solution {
public:
    vector<int> intersection(vector<vector<int>>& nums) {
        vector<int> cnt(1001, 0);
        for (const auto& arr : nums) {
            for (int x : arr) cnt[x]++;
        }
        int n = nums.size();
        vector<int> ans;
        for (int i = 1; i <= 1000; i++) {
            if (cnt[i] == n) ans.push_back(i);
        }
        return ans;
    }
};

class Solution {
    public List<Integer> intersection(int[][] nums) {
        int[] cnt = new int[1001];
        for (int[] arr : nums) {
            for (int x : arr) cnt[x]++;
        }
        int n = nums.length;
        List<Integer> ans = new ArrayList<>();
        for (int i = 1; i <= 1000; i++) {
            if (cnt[i] == n) ans.add(i);
        }
        return ans;
    }
}

/**
 * @param {number[][]} nums
 * @return {number[]}
