var intersection = function(nums) {
    const cnt = new Array(1001).fill(0);
    for (const arr of nums) {
        for (const x of arr) cnt[x]++;
    }
    const n = nums.length;
    const ans = [];
    for (let i = 1; i <= 1000; i++) {
        if (cnt[i] === n) ans.push(i);
    }
    return ans;
};
